create table if not exists public.reply_likes (id uuid primary key default gen_random_uuid(),reply_id uuid not null references public.replies(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),unique(reply_id,user_id));
create table if not exists public.reply_reposts (id uuid primary key default gen_random_uuid(),reply_id uuid not null references public.replies(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),unique(reply_id,user_id));
create table if not exists public.reply_bookmarks (id uuid primary key default gen_random_uuid(),reply_id uuid not null references public.replies(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),unique(reply_id,user_id));
create table if not exists public.reply_shares (id uuid primary key default gen_random_uuid(),reply_id uuid not null references public.replies(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),unique(reply_id,user_id));
create table if not exists public.reply_reactions (id uuid primary key default gen_random_uuid(),reply_id uuid not null references public.replies(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,emoji text not null,created_at timestamptz not null default now(),unique(reply_id,user_id,emoji));
create index if not exists reply_likes_reply_idx on public.reply_likes(reply_id); create index if not exists reply_reposts_reply_idx on public.reply_reposts(reply_id); create index if not exists reply_bookmarks_reply_idx on public.reply_bookmarks(reply_id); create index if not exists reply_shares_reply_idx on public.reply_shares(reply_id); create index if not exists reply_reactions_reply_idx on public.reply_reactions(reply_id);
alter table public.reply_likes enable row level security; alter table public.reply_reposts enable row level security; alter table public.reply_bookmarks enable row level security; alter table public.reply_shares enable row level security; alter table public.reply_reactions enable row level security;
drop policy if exists reply_likes_read on public.reply_likes; create policy reply_likes_read on public.reply_likes for select using (true); drop policy if exists reply_likes_owner_write on public.reply_likes; create policy reply_likes_owner_write on public.reply_likes for all to authenticated using (user_id=auth.uid()) with check (user_id=auth.uid());
drop policy if exists reply_reposts_read on public.reply_reposts; create policy reply_reposts_read on public.reply_reposts for select using (true); drop policy if exists reply_reposts_owner_write on public.reply_reposts; create policy reply_reposts_owner_write on public.reply_reposts for all to authenticated using (user_id=auth.uid()) with check (user_id=auth.uid());
drop policy if exists reply_bookmarks_owner on public.reply_bookmarks; create policy reply_bookmarks_owner on public.reply_bookmarks for all to authenticated using (user_id=auth.uid()) with check (user_id=auth.uid());
drop policy if exists reply_shares_read on public.reply_shares; create policy reply_shares_read on public.reply_shares for select using (true); drop policy if exists reply_shares_owner_write on public.reply_shares; create policy reply_shares_owner_write on public.reply_shares for all to authenticated using (user_id=auth.uid()) with check (user_id=auth.uid());
drop policy if exists reply_reactions_read on public.reply_reactions; create policy reply_reactions_read on public.reply_reactions for select using (true); drop policy if exists reply_reactions_owner_write on public.reply_reactions; create policy reply_reactions_owner_write on public.reply_reactions for all to authenticated using (user_id=auth.uid()) with check (user_id=auth.uid());
create or replace function public.testagram_toggle_reply_like(p_reply_id uuid) returns jsonb language plpgsql security invoker set search_path=public as $$ declare u uuid:=auth.uid(); a boolean; n bigint; begin if u is null then raise exception using errcode='42501',message='Authentication required'; end if; select exists(select 1 from reply_likes where reply_id=p_reply_id and user_id=u) into a; if a then delete from reply_likes where reply_id=p_reply_id and user_id=u; else insert into reply_likes(reply_id,user_id) values(p_reply_id,u); end if; select count(*) into n from reply_likes where reply_id=p_reply_id; return jsonb_build_object('active',not a,'count',n); end $$;
create or replace function public.testagram_toggle_reply_repost(p_reply_id uuid) returns jsonb language plpgsql security invoker set search_path=public as $$ declare u uuid:=auth.uid(); a boolean; n bigint; begin if u is null then raise exception using errcode='42501',message='Authentication required'; end if; select exists(select 1 from reply_reposts where reply_id=p_reply_id and user_id=u) into a; if a then delete from reply_reposts where reply_id=p_reply_id and user_id=u; else insert into reply_reposts(reply_id,user_id) values(p_reply_id,u); end if; select count(*) into n from reply_reposts where reply_id=p_reply_id; return jsonb_build_object('active',not a,'count',n); end $$;
create or replace function public.testagram_toggle_reply_bookmark(p_reply_id uuid) returns jsonb language plpgsql security invoker set search_path=public as $$ declare u uuid:=auth.uid(); a boolean; n bigint; begin if u is null then raise exception using errcode='42501',message='Authentication required'; end if; select exists(select 1 from reply_bookmarks where reply_id=p_reply_id and user_id=u) into a; if a then delete from reply_bookmarks where reply_id=p_reply_id and user_id=u; else insert into reply_bookmarks(reply_id,user_id) values(p_reply_id,u); end if; select count(*) into n from reply_bookmarks where reply_id=p_reply_id; return jsonb_build_object('active',not a,'count',n); end $$;
create or replace function public.testagram_record_reply_share(p_reply_id uuid) returns jsonb language plpgsql security invoker set search_path=public as $$ declare u uuid:=auth.uid(); n bigint; begin if u is null then raise exception using errcode='42501',message='Authentication required'; end if; insert into reply_shares(reply_id,user_id) values(p_reply_id,u) on conflict(reply_id,user_id) do nothing; select count(*) into n from reply_shares where reply_id=p_reply_id; return jsonb_build_object('count',n); end $$;
create or replace function public.testagram_reply_engagement(p_reply_id uuid) returns jsonb language plpgsql security invoker set search_path=public as $$ declare u uuid:=auth.uid(); begin return jsonb_build_object('likes',(select count(*) from reply_likes where reply_id=p_reply_id),'reposts',(select count(*) from reply_reposts where reply_id=p_reply_id),'bookmarks',(select count(*) from reply_bookmarks where reply_id=p_reply_id),'shares',(select count(*) from reply_shares where reply_id=p_reply_id),'is_liked',exists(select 1 from reply_likes where reply_id=p_reply_id and user_id=u),'is_reposted',exists(select 1 from reply_reposts where reply_id=p_reply_id and user_id=u),'is_bookmarked',exists(select 1 from reply_bookmarks where reply_id=p_reply_id and user_id=u),'replies',(select count(*) from replies where parent_reply_id=p_reply_id)); end $$;
grant execute on function public.testagram_toggle_reply_like(uuid),public.testagram_toggle_reply_repost(uuid),public.testagram_toggle_reply_bookmark(uuid),public.testagram_record_reply_share(uuid),public.testagram_reply_engagement(uuid) to authenticated;